// Omit excludes the specified fields/columns from the query result.
// By default, all fields are selected. Use this method to select only specific fields.
//
// Example:
//
//	var v []struct {
//	  CreateTime time.Time `json:"create_time,omitempty"`
//	  UpdateTime time.Time `json:"update_time,omitempty"`
//	  ParentID int64 `json:"parent_id,omitempty"`
//	  Keyword string `json:"keyword,omitempty"`
//	  Scope string `json:"scope,omitempty"`
//	  Name string `json:"name,omitempty"`
//	  I18n string `json:"i18n,omitempty"`
//	  Type view.Type `json:"type,omitempty"`
//	  Component string `json:"component,omitempty"`
//	  Path string `json:"path,omitempty"`
//	  Icon string `json:"icon,omitempty"`
//	  Sequence int `json:"sequence,omitempty"`
//	  TreePath string `json:"tree_path,omitempty"`
//	  Description string `json:"description,omitempty"`
//	  Properties string `json:"properties,omitempty"`
//	  Status enums.Status `json:"status,omitempty"`
//	}
//
//	client.View.Query().
//	  Omit(
//	  view.FieldCreateTime,
//	  view.FieldUpdateTime,
//	  view.FieldParentID,
//	  view.FieldKeyword,
//	  view.FieldScope,
//	  view.FieldName,
//	  view.FieldI18n,
//	  view.FieldType,
//	  view.FieldComponent,
//	  view.FieldPath,
//	  view.FieldIcon,
//	  view.FieldSequence,
//	  view.FieldTreePath,
//	  view.FieldDescription,
//	  view.FieldProperties,
//	  view.FieldStatus,
//	  ).
//	  Scan(ctx, &v)
func (vq *ViewQuery) Omit(fields ...string) *ViewSelect {
	omits := make(map[string]struct{}, len(fields))
	for i := range fields {
		omits[fields[i]] = struct{}{}
	}
	for _, col := range view.Columns {
		if _, ok := omits[col]; !ok {
			vq.ctx.Fields = append(vq.ctx.Fields, col)
		}
	}

	sbuild := &ViewSelect{ViewQuery: vq}
	sbuild.label = view.Label
	sbuild.flds, sbuild.scan = &vq.ctx.Fields, sbuild.Scan
	return sbuild
}

